"""Castward trust pages and shared consent controls."""
from photography import credits
from legal_content import LEGAL, legal_body
PAGES = {
'about': ('About Castward', [
('Find your water. Go prepared.', 'Castward brings fishing destinations, environment guides and preparation checklists into one atlas. Coverage includes source-linked research and editorial preparation frameworks. It is not a live conditions or regulations service. Check each guide’s source notes and confirm details locally.'),
('Plans without an account', 'Create a fishing plan and save it in your browser. There is no central plan account. Export a copy before you clear browser data. Contact us about corrections, guide listings, partnerships or press requests.'),
('Scenes, not evidence', 'Our images and videos include AI-generated scenery. They show representative fishing environments, not verified footage of the named destinations. Video scenes use AI animation from generated images. They do not document actual conditions, trips or catches. See the <a href="/videos/">video collection</a> for film descriptions. Photo and AI source notes appear below.'),
('Independent decisions', 'Castward is the site operator. We do not claim local guide credentials or guarantee any third-party service. Future affiliate and booking links will carry relevant disclosures. Reach us at contact@castward.app.')])}

def install(pages, add, intro, footer):
    for slug,(title,sections) in PAGES.items():
        body=intro('CASTWARD / TRUST',title,'Last updated November 10, 2026')+'<article class="wrap prose trust-content">'+''.join('<section><h2>'+h+'</h2><p>'+p+'</p></section>' for h,p in sections)+'</article>'
        if slug=='about': body+=credits().replace('<section class="section">','<section class="section" id="photo-credits">',1)
        add('/'+slug+'/',title+' | Castward',title+' for the Castward fishing atlas, local plans and contact service.',body,'trust')
    for slug, (title, sections) in LEGAL.items():
        add('/'+slug+'/', title+' | Castward', title+' for the Castward fishing atlas, planner and contact service.', legal_body(slug,title,sections,intro), 'trust')
        pages['/'+slug+'/']['modified']='2026-11-10'
    form='''<div class="wrap trust-content"><p>For trip questions, corrections, guide listings, partnerships or press, email <span class="footer-email">contact@castward.app</span>.</p><p>For privacy requests, use privacy@castward.app. We cannot confirm a booking or provide emergency assistance through this form.</p><form id="contact-form"><div class="form-field"><label for="contact-name">Name</label><input id="contact-name" name="name" autocomplete="name" maxlength="100" required></div><div class="form-field"><label for="contact-email">Email</label><input id="contact-email" name="email" type="email" autocomplete="email" maxlength="254" required></div><div class="form-field"><label for="contact-topic">Topic</label><select id="contact-topic" name="topic"><option value="trip question">Trip question</option><option value="guide or captain listing">Guide or captain listing</option><option value="partnership">Partnership</option><option value="press">Press</option><option value="other">Other</option></select></div><div class="form-field"><label for="contact-message">Message</label><textarea id="contact-message" name="message" rows="7" minlength="10" maxlength="5000" required></textarea></div><div class="contact-honey" aria-hidden="true"><label for="contact-website">Leave this field empty</label><input id="contact-website" name="website" tabindex="-1" autocomplete="off"></div><label class="consent-line"><input name="consent" type="checkbox" required><span>I agree that Castward may use these details to answer my request, as described in the <a href="/privacy/">privacy policy</a>. This does not subscribe me to marketing.</span></label><button type="submit" class="btn">Send message</button><p id="contact-status" role="status" aria-live="polite"></p></form><noscript><p>Please email contact@castward.app. This form requires JavaScript.</p></noscript></div>'''
    add('/contact/','Contact Castward','Contact Castward about fishing trips, guide listings, partnerships, press or site corrections.',intro('CASTWARD / CONTACT','Let’s talk about the water.','Send a question or help us improve the atlas.')+form,'contact')
    links=''.join(f'<a href="/{slug}/">{label}</a>' for slug,label in [('about','About'),('contact','Contact'),('privacy','Privacy'),('terms','Terms'),('cookies','Cookies'),('disclaimer','Fishing safety'),('affiliate-disclosure','Affiliate disclosure'),('accessibility','Accessibility')])
    footer=footer.replace('</footer>','<div class="wrap"><nav class="footer-links" aria-label="Trust and legal">'+links+'</nav><p class="footer-email">contact@castward.app</p><button type="button" class="cookie-settings" data-cookie-settings>Cookie settings</button><a class="privacy-choice" href="/privacy/#do-not-sell">Do Not Sell or Share My Personal Information</a></div></footer>')
    footer+='''<section id="cookie-banner" aria-label="Cookie consent"><p>Castward uses optional Google Analytics to understand site use. We load analytics only with your consent. Your local fishing plan works either way. <a href="/cookies/">Cookies and storage</a></p><div class="action-row"><button type="button" class="btn" data-consent="accept">Accept</button><button type="button" class="btn outline" data-consent="reject">Reject non-essential</button></div></section>'''
    return footer
